        if (processIdentity?.processGroupIsolated && isolatedProcessGroupAlive(processIdentity.pgid)) {
          termSent = signalIsolatedProcessGroup(processIdentity.pgid, 'SIGTERM') || termSent;
          await new Promise(resolveWait => setTimeout(resolveWait, HOST_RUN_PROCESS_GROUP_TERM_GRACE_MS));
